#!/usr/bin/env node

/**
 * sync-narrative.mjs
 *
 * Extracts structured data from docs/narrative-design.md (the single source of truth)
 * and generates importable config files for the narrative-writer pipeline.
 *
 * Usage: node scripts/sync-narrative.mjs
 *
 * Generates:
 *   scripts/narrative-writer/generated/translation-table.mjs
 *   scripts/narrative-writer/generated/anchor-facts.mjs
 *   scripts/narrative-writer/generated/layer-config.mjs
 *
 * These files are imported by system-context.mjs, config.mjs, etc.
 * Do NOT edit the generated files — edit narrative-design.md and re-run this script.
 */

import { readFileSync, writeFileSync } from 'fs'
import { join, dirname } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const DOC_PATH = join(__dirname, '..', 'docs', 'narrative-design.md')
const OUT_DIR = join(__dirname, 'narrative-writer', 'generated')

const doc = readFileSync(DOC_PATH, 'utf-8')

const HEADER = `// AUTO-GENERATED by sync-narrative.mjs from docs/narrative-design.md
// Do NOT edit this file — edit the narrative design document and re-run:
//   node scripts/sync-narrative.mjs
// Generated: ${new Date().toISOString().split('T')[0]}
`

// ─── Markdown table parser ───

function parseMdTable(text) {
  const lines = text.trim().split('\n').filter(l => l.includes('|'))
  if (lines.length < 2) return []
  const headers = lines[0].split('|').map(c => c.trim()).filter(Boolean)
  // skip separator line (line[1])
  const rows = []
  for (let i = 2; i < lines.length; i++) {
    const cells = lines[i].split('|').map(c => c.trim()).filter(Boolean)
    if (cells.length >= headers.length) {
      const row = {}
      headers.forEach((h, j) => { row[h] = cells[j] || '' })
      rows.push(row)
    }
  }
  return rows
}

// ─── Extract section between two headings ───

function extractSection(md, startPattern, endPattern) {
  const startMatch = md.match(new RegExp(`^${startPattern}.*$`, 'm'))
  if (!startMatch) return ''
  const startIdx = startMatch.index + startMatch[0].length
  let endIdx = md.length
  if (endPattern) {
    const endMatch = md.slice(startIdx).match(new RegExp(`^${endPattern}`, 'm'))
    if (endMatch) endIdx = startIdx + endMatch.index
  }
  return md.slice(startIdx, endIdx)
}

// ─── 1. Translation Table ───

function extractTranslationTable() {
  // Find the extended translation table section
  const section = extractSection(doc, '### 扩展版设定翻译表', '###')

  // Find ALL markdown tables in the section (there are multiple: objects, actions, spaces)
  const tableRegex = /(\|[^\n]+\|\n\|[-|:\s]+\|\n(?:\|[^\n]+\|\n?)+)/g
  const allRows = []
  let match
  while ((match = tableRegex.exec(section)) !== null) {
    allRows.push(...parseMdTable(match[1]))
  }

  // Normalize: extract game_term, setting_zh, setting_en
  const entries = []
  for (const row of allRows) {
    const keys = Object.keys(row)
    if (keys.length >= 3) {
      const game = row[keys[0]].replace(/\*\*/g, '').trim()
      const zh = row[keys[1]].replace(/\*\*/g, '').trim()
      const en = row[keys[2]].replace(/\*\*/g, '').trim()
      if (game && zh) {
        entries.push({ game, zh, en })
      }
    }
  }

  return entries
}

// ─── 2. Anchor Facts ───

function extractAnchorFacts() {
  const anchors = {}

  // Find the fact table section by looking for the heading
  const factStart = doc.indexOf('### 锚点人物事实表')
  if (factStart === -1) return anchors
  // Find the next ### heading after it
  const nextSection = doc.indexOf('\n### ', factStart + 1)
  const factSection = doc.slice(factStart, nextSection === -1 ? undefined : nextSection)

  const anchorDefs = [
    { id: 'scriptor_a', heading: '守卷人 A' },
    { id: 'scriptor_b', heading: '守卷人 B' },
    { id: 'scriptor_c', heading: '守卷人 C' },
    { id: 'last_signatory', heading: '议会末席' },
    { id: 'd_0001', heading: 'D-0001' },
  ]

  for (const { id, heading } of anchorDefs) {
    const idx = factSection.indexOf(`#### ${heading}`)
    if (idx === -1) continue
    const afterHeading = factSection.slice(idx)
    // Get the first table after this heading
    const tableMatch = afterHeading.match(/(\|[^\n]+\|\n\|[-|:\s]+\|\n(?:\|[^\n]+\|\n?)+)/)
    if (!tableMatch) continue
    const rows = parseMdTable(tableMatch[1])
    const facts = {}
    for (const row of rows) {
      const keys = Object.keys(row)
      if (keys.length >= 2) {
        const key = row[keys[0]].trim()
        const val = row[keys[1]].trim()
        if (key && key !== '事实') facts[key] = val
      }
    }
    if (Object.keys(facts).length > 0) anchors[id] = facts
  }

  return anchors
}

// ─── 3. Layer Config ───

function extractLayerConfig() {
  const section = extractSection(doc, '#### 12 层氛围渐进', '####|###')
  const table = section.match(/(\|.+\|[\s\S]*?)(?=\n\n|\n####|\n###|$)/)
  if (!table) return []
  return parseMdTable(table[1])
}

// ─── Generate files ───

function generate() {
  console.log('提取数据从 docs/narrative-design.md ...\n')

  // 1. Translation table
  const translations = extractTranslationTable()
  console.log(`  翻译表: ${translations.length} 条`)
  writeFileSync(join(OUT_DIR, 'translation-table.mjs'), HEADER + `
export const TRANSLATION_TABLE = ${JSON.stringify(translations, null, 2)}

// Quick lookup: game term → setting term (zh)
export const TERM_ZH = Object.fromEntries(
  TRANSLATION_TABLE.map(e => [e.game, e.zh])
)

// Quick lookup: game term → setting term (en)
export const TERM_EN = Object.fromEntries(
  TRANSLATION_TABLE.map(e => [e.game, e.en])
)
`)

  // 2. Anchor facts
  const anchors = extractAnchorFacts()
  console.log(`  锚点人物: ${Object.keys(anchors).length} 个`)
  writeFileSync(join(OUT_DIR, 'anchor-facts.mjs'), HEADER + `
export const ANCHOR_FACTS = ${JSON.stringify(anchors, null, 2)}
`)

  // 3. Layer config
  const layers = extractLayerConfig()
  console.log(`  层级配置: ${layers.length} 条`)
  writeFileSync(join(OUT_DIR, 'layer-config.mjs'), HEADER + `
export const LAYER_CONFIG = ${JSON.stringify(layers, null, 2)}
`)

  console.log(`\n✅ 生成完成 → scripts/narrative-writer/generated/`)
  console.log('   translation-table.mjs')
  console.log('   anchor-facts.mjs')
  console.log('   layer-config.mjs')
}

generate()
